package com.dossier.api.service.privacy;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The data map as code (REAL-GAPS-C T1.1): every table that holds a user or organization reference, with what happens to it on erasure, what
 * the data export says about it, and which retention job (if any) purges it over time. It is the register of processing the privacy policy promises
 * against, and it is what keeps that promise honest: {@code DataMapIT} reads the live schema and FAILS when a table with a user or organization
 * reference is not listed here, when an entry names a table or column that no longer exists, when an export section named here is missing from the
 * real export, or when a retention job names the wrong table. Adding a table therefore means adding a row here, which is the moment to decide how it
 * is erased and exported.
 *
 * <p>Columns marked {@link Key#USER_ID} or {@link Key#LOGIN} are the ones {@code ErasureCensus} counts before and after an erasure to build the purge
 * report; a table whose rows hang off a parent (no direct user column) lists none and is covered through its parent's erasure.
 */
public final class DataMap {

    /** How a column identifies the person. */
    public enum Key {
        USER_ID,
        LOGIN
    }

    /** A column that points at the person. */
    public record Col(String name, Key key) {}

    /**
     * One table. {@code exportSection} is the key of the section in the account export that carries its rows, or null when it is deliberately not
     * exported, in which case {@code exportNote} says why. {@code retentionJob} is the {@link RetentionTarget#job()} that purges it, or null.
     */
    public record Entry(String table, DataClass cls, List<Col> cols, String erasure, String exportSection, String exportNote, String retentionJob) {}

    private static final Map<String, Entry> ENTRIES;

    static {
        List<Entry> e = new ArrayList<>();

        // ---- rows one account owns -------------------------------------------------------------------------------------------------------------
        owned(e, "ai_answer", "user_id", "AccountDeletionService", "aiAnswers");
        owned(e, "application", "user_id", "AccountDeletionService (rows and attachment files)", "applications");
        child(e, "application_event", "TrackerDataService.deleteAllForUser (before its application)", "applicationEvents");
        child(e, "application_note", "TrackerDataService.deleteAllForUser (before its application)", "applicationNotes");
        owned(e, "interview", "user_id", "TrackerDataService.deleteAllForUser", "interviews");
        owned(e, "bio", "user_id", "AccountDeletionService", "bio");
        owned(e, "customer_note", "user_id", "AccountDeletionService.endBilling", null, "staff-written notes about the account; disclosed through support on request, not part of the self-service copy");
        owned(e, "field_cache", "user_id", "AccountDeletionService", "fieldCache");
        owned(e, "inbox_connection", "user_id", "InboxService.deleteAllForUser (the stored App Password goes with the row)", "inbox");
        owned(e, "inbox_folder_state", "user_id", "InboxService.deleteAllForUser", null, "polling bookkeeping (a mailbox cursor), no content");
        owned(e, "inbox_hold", "user_id", "InboxService.deleteAllForUser (the rows go with the mail and the account by cascade)", null, "a status change a mail proposed and the person has not answered yet: a scrubbed snippet, ids and a state, no mail text");
        owned(e, "inbox_message", "user_id", "InboxService.deleteAllForUser; also the nightly inbox retention", "inbox");
        owned(e, "job_feedback", "user_id", "JobSearchDataService.deleteAllForUser", "jobFeedback");
        owned(e, "job_fit", "user_id", "JobFitService.deleteAllForUser", null, "derived AI score, regenerated on demand");
        owned(e, "job_match", "user_id", "JobMatchService.deleteAllForUser", null, "derived match list, regenerated by the daily job");
        owned(e, "job_match_setting", "user_id", "JobMatchService.deleteAllForUser", null, "a single on/off switch and last-run status");
        owned(e, "resume_match", "user_id", "ResumeMatchService.deleteAllForUser", null, "derived AI score, regenerated on demand");
        owned(e, "resume_tailor", "user_id", "ResumeTailorService.deleteAllForUser", null, "derived AI output, regenerated on demand");
        owned(e, "resume_ai_proposal", "user_id", "ResumeBuilderDataService.deleteAllForUser", null, "unaccepted AI suggestions for a resume");
        owned(e, "notification", "user_id", "NotificationService.deleteAllForUser", "notifications");
        owned(e, "notification_preference", "user_id", "AccountDeletionService (FK cascade with the user row)", "notificationPreferences");
        owned(e, "onboarding_draft", "user_id", "ResumeBuilderDataService.deleteOnboardingDraft", "onboardingDraft");
        owned(e, "profile_item", "user_id", "ResumeBuilderDataService.deleteAllForUser", "profileItems");
        owned(e, "profile_suggestion", "user_id", "ProfileSuggestionService.deleteAllForUser", "profileSuggestions");
        owned(e, "refresh_token", "user_id", "RefreshTokenService.deleteAllForUser; also the retention sweep for expired rows", null, "session security records, no personal content", "REFRESH_TOKEN");
        owned(e, "resume", "user_id", "AccountDeletionService (files first, then rows)", "resumes");
        owned(e, "resume_doc", "user_id", "ResumeBuilderDataService.deleteAllForUser (files first: built PDFs, profile photos, originals, thumbnails, by prefix)", "resumeDocs");
        owned(e, "resume_doc_version", "user_id", "ResumeBuilderDataService.deleteAllForUser", null, "version history of resumeDocs, the current version is exported");
        owned(e, "subscription", "user_id", "AccountDeletionService.endBilling (Stripe subscription cancelled first)", null, "billing record; Stripe holds the payment history and the person asks Stripe for that copy");
        // personal subscription module (subscription-merge): what the person bought, the plan grants and usage ledger behind their entitlements, and the notices sent to them
        owned(e, "subscription_addon", "user_id", "PersonalBillingErasure (before the subscription row; the Stripe subscription is cancelled first)", null, "mirror of the Stripe subscription items the person bought; Stripe holds the payment history and the person asks Stripe for that copy");
        owned(e, "personal_subscription_change", "user_id", "PersonalBillingErasure (before the subscription row)", null, "audit of the person's own plan and add-on changes, mirrored from Stripe");
        owned(e, "subscription_quote", "user_id", "PersonalBillingErasure (anonymous pricing-page quotes have no user and expire on their own)", null, "short-lived priced baskets, recomputed on demand");
        owned(e, "entitlement_grant", "user_id", "FK cascade with the user row", null, "plan grants (promotions, support) that decide what the person may use; the grantor is an administrator login");
        owned(e, "personal_usage_counter", "user_id", "FK cascade with the user row", null, "metered-usage counters per period; regenerated, no content");
        owned(e, "service_lock", "user_id", "FK cascade with the user row", null, "read-only locks left by a retired plan; a new account on the same login must not inherit them");
        owned(e, "billing_notice", "user_id", "FK cascade with the user row", null, "log of plan-retirement notices sent to the person, kept only to avoid sending one twice");
        owned(e, "plan_retirement_item", "user_id", "FK cascade with the user row (organization-scope rows carry an org_id and no user, they follow the organization)", null, "the person's pending choice in a plan retirement, shown on the billing page");
        owned(e, "terms_acceptance", "user_id", "AccountDeletionService (FK cascade with the user row)", "termsAcceptance");
        owned(e, "data_export_job", "user_id", "AccountDeletionService (FK cascade; the ZIP files go with the user's file prefixes)", null, "the export job itself");
        owned(e, "account_deletion_request", "user_id", "FK cascade with the user row", null, "the pending erasure itself");
        owned(e, "jhi_user_authority", "user_id", "UserService.deleteUser (join rows go with the account)", null, "role grants, shown in the account section");
        owned(e, "ext_connect_code", "user_id", "AccountDeletionService (extConnectCodeRepository.deleteByUserId)", null, "a 60-second single-use code, no content");
        owned(e, "resume_access", "owner_user_id", "ResumeBuilderDataService.deleteAllForUser", "resumeShares");
        owned(e, "resume_view_event", "owner_user_id", "ResumeBuilderDataService.deleteAllForUser", null, "view analytics of the person's shared resumes (who looked and when)");
        // keyed by login string rather than id
        ownedByLogin(e, "ai_usage", "login", "AccountDeletionService.forgetAiUsage", null, "monthly draft counters");
        ownedByLogin(e, "ai_quota_override", "login", "AccountDeletionService (aiQuotaOverrideRepository.deleteByLogin): a new account on the same login must not inherit a quota", null, "an administrator-set budget");
        ownedByLogin(e, "bug_report", "user_login", "AccountDeletionService (bugReportRepository.deleteByUserLogin); also the retention sweep for resolved reports", "bugReports", null, "BUG_REPORT");
        ownedByLogin(e, "sales_inquiry", "user_login", "AccountDeletionService (salesInquiryRepository.deleteByUserLogin)", "salesInquiries", null, null);

        // ---- both an id/login and a second reference (the person as a viewer on somebody else's resume) -----------------------------------------
        add(e, new Entry("resume_view_event", DataClass.USER_OWNED, List.of(new Col("owner_user_id", Key.USER_ID), new Col("viewer_login", Key.LOGIN)), "ResumeBuilderDataService.deleteAllForUser / deleteSharingAsViewer", null, "view analytics of the person's shared resumes (who looked and when)", null));
        add(e, new Entry("resume_access", DataClass.USER_OWNED, List.of(new Col("owner_user_id", Key.USER_ID), new Col("subject_login", Key.LOGIN)), "ResumeBuilderDataService.deleteAllForUser / deleteSharingAsViewer", "resumeShares", null, null));

        add(e, new Entry("personal_usage_event", DataClass.USER_OWNED, List.of(new Col("user_id", Key.USER_ID), new Col("login", Key.LOGIN)), "FK cascade with the user row", null, "metered-usage reservations; the ai_call ledger keeps the spend without the login", null));

        // ---- kept after the account goes, without the link to the person -------------------------------------------------------------------------
        add(e, new Entry("ai_call", DataClass.USER_ANONYMISED, List.of(new Col("login", Key.LOGIN)), "AccountDeletionService.forgetAiUsage (login nulled, spend kept for accounting); also the retention sweep", null, "token and cost ledger, never prompts or answers", "AI_CALL"));
        add(e, new Entry("stripe_event", DataClass.USER_ANONYMISED, List.of(new Col("user_id", Key.USER_ID)), "StripeEventRepository.forget (the link to the person is removed, the event record stays)", null, "Stripe webhook log", null));
        add(e, new Entry("invoice", DataClass.USER_ANONYMISED, List.of(new Col("user_id", Key.USER_ID)), "AccountDeletionService.endBilling (InvoiceRepository.pseudonymise: the user id becomes 0, the money record stays for accounting)", null, "mirror of the Stripe invoice; Stripe holds the original and the person asks Stripe for that copy", null));
        add(e, new Entry("invoice_line", DataClass.USER_ANONYMISED, List.of(new Col("user_id", Key.USER_ID)), "AccountDeletionService.endBilling (InvoiceLineRepository.pseudonymise: the user id becomes 0, amounts and descriptions stay)", null, "lines of the mirrored Stripe invoice", null));

        // ---- short-lived security rows ----------------------------------------------------------------------------------------------------------
        add(e, new Entry("admin_mfa_challenge", DataClass.EPHEMERAL, List.of(new Col("user_id", Key.USER_ID), new Col("login", Key.LOGIN)), "AccountDeletionService (adminMfaChallengeRepository.deleteByUserId); expires in minutes anyway", null, "a pending sign-in code check, expires in minutes", null));

        // ---- accountability trails keyed by an administrator's login ---------------------------------------------------------------------------
        add(e, new Entry("admin_audit_event", DataClass.AUDIT_RETAINED, List.of(), "not deleted with a person: the trail of what administrators did; purged by the retention sweep", null, "accountability record of administrator actions", "ADMIN_AUDIT"));
        add(e, new Entry("catalog_change", DataClass.AUDIT_RETAINED, List.of(), "not deleted with a person: the catalog and plan-builder change trail, keyed by the administrator's login", null, "platform pricing configuration history", null));
        add(e, new Entry("app_setting", DataClass.AUDIT_RETAINED, List.of(), "not deleted with a person: names the administrator who last changed a setting", null, "platform configuration", null));
        add(e, new Entry("app_setting_history", DataClass.AUDIT_RETAINED, List.of(), "not deleted with a person: the settings change trail", null, "platform configuration history", null));
        add(e, new Entry("retention_run", DataClass.AUDIT_RETAINED, List.of(), "not deleted with a person: counts of what a retention sweep removed, and which administrator ran it", null, "retention run log", null));
        add(e, new Entry("account_deletion_report", DataClass.SYSTEM, List.of(), "carries no identity (a former numeric id and counts); purged by the retention sweep", null, "purge report", "DELETION_REPORT"));

        // ---- contacts not linked to an account ---------------------------------------------------------------------------------------------------
        add(e, new Entry("email_subscriber", DataClass.UNLINKED_CONTACT, List.of(), "removed by the unsubscribe link or by an administrator; not linked to any account", null, "newsletter address", null));

        // ---- the account table ---------------------------------------------------------------------------------------------------------------------
        add(e, new Entry("jhi_user", DataClass.ACCOUNT_ROOT, List.of(), "UserService.deleteUser, last", "account", null, null));

        // ---- organization records that mention people ----------------------------------------------------------------------------------------------
        String orgPeople = "organization record: follows the organization lifecycle (offboarding / close), not a personal account erasure";
        for (String t : List.of("client_contact", "consultant_profile", "cws_notification_pref", "hr_employee", "org_billing_account", "org_branding", "org_policy_version", "idempotency_record")) {
            add(e, new Entry(t, DataClass.ORG_PEOPLE, List.of(), orgPeople + (t.equals("idempotency_record") ? " (purged by its own nightly job)" : ""), null, "organization-held record about a person who is not the account holder, or an organization setting", null));
        }
        add(e, new Entry("data_share_event", DataClass.ORG_PEOPLE, List.of(), "OrgMembershipPrivacyService.eraseFor (one ERASED event keeps the proof; the history holds no profile data)", null, "consent history, listed in the organizations section", null));
        add(e, new Entry("org_audit_event", DataClass.ORG_PEOPLE, List.of(), "the organization's accountability trail, keyed by login strings; an enterprise login is never written, the seat label is", null, "organization audit trail", null));
        add(e, new Entry("org_member", DataClass.ORG_PEOPLE, List.of(), "OrgMembershipPrivacyService.eraseFor (user id, invite e-mail and name cleared, status ERASED)", "organizations", null, null));

        // ---- no user or organization reference ----------------------------------------------------------------------------------------------------
        for (String t : List.of("databasechangelog", "databasechangeloglock", "feature_definition", "fill_event", "jhi_authority", "jhi_date_time_wrapper", "job_lease", "job_posting", "job_source", "product", "secret_canary", "org_role_permission")) {
            add(e, new Entry(t, DataClass.SYSTEM, List.of(), "no user or organization reference", null, "not personal data", null));
        }

        // ---- organization-owned records (reference seats and organizations, never accounts) -----------------------------------------------------
        for (String t : List.of(
            "billing_drift", "client_account", "client_note", "client_requirement", "consultant_license", "consultant_skill",
            "cws_availability_block", "cws_availability_history", "cws_certification", "cws_interview_detail", "cws_interview_feedback",
            "cws_job_source", "cws_match_interest", "cws_match_view", "cws_notification", "cws_offer", "cws_offer_event", "cws_opportunity_response",
            "cws_placement_activity", "cws_placement_checklist", "cws_placement_detail", "cws_placement_meeting", "cws_placement_milestone",
            "cws_prep_answer", "cws_prep_check", "cws_prep_session", "cws_profile_detail", "cws_profile_pref", "cws_resume_activity", "cws_saved_job",
            "cws_saved_search", "cws_setting", "cws_setting_event", "cws_submission", "cws_task", "cws_task_detail", "cws_work_preference", "data_share",
            "feature_credit", "finance_forecast_input", "finance_invoice", "finance_payment", "finance_placement_period", "finance_placement_terms",
            "finance_timesheet", "hr_document_requirement", "hr_employee_note", "hr_lifecycle_event", "hr_offboarding_task", "hr_onboarding_item",
            "hr_training", "hr_training_record", "job_data_event", "license_change", "license_feature", "marketer_assignment", "marketer_assignment_event", "marketer_assignment_schedule", "marketer_capacity",
            "mkt_activity", "mkt_benchmark", "mkt_followup", "mkt_followup_event", "mkt_goal", "mkt_interview_event", "mkt_interview_feedback",
            "mkt_interview_meta", "mkt_interview_prep_item", "mkt_job_meta", "mkt_job_stream", "mkt_opportunity", "mkt_opportunity_event",
            "mkt_resume_event", "mkt_saved_search", "mkt_saved_view", "mkt_stream_alert", "mkt_stream_rule", "mkt_stream_sync_log", "mkt_submission",
            "mkt_submission_event", "mkt_submission_view", "mkt_task", "mkt_task_event", "org_assignment", "org_billing_adjustment",
            "org_branding_version", "org_contract", "org_contract_price", "org_domain", "org_group", "org_hostname", "org_invite_batch", "org_invoice",
            "org_invoice_line", "org_join_code", "org_member_dismissal", "org_member_offboarding", "org_member_role", "org_payment",
            "org_payment_method", "org_plan_feature", "org_policy", "org_resume", "org_resume_experience", "org_role", "org_setting", "org_spend_entry",
            "org_subscription", "org_subscription_item", "pipeline_application_link", "placement_event", "placement_extension", "placement_note",
            "report_definition", "report_export", "report_metric", "report_recipient", "report_run", "requirement_match", "requirement_skill",
            "subscription_change", "talent_application", "talent_application_event", "talent_application_note", "talent_interview",
            "talent_interview_event", "talent_interview_feedback", "talent_interview_interviewer", "talent_placement", "usage_alert", "usage_counter",
            "usage_event",
            // Sprint 2 "prepare": a consultant's prepared-application batches. They carry the organization and seat/match ids, never an account
            "prepare_event", "prepare_item", "prepare_session"
        )) {
            add(e, new Entry(t, DataClass.ORG_TENANT, List.of(), "organization-owned: follows the organization; the person is a seat (org_member), which erasure anonymises", null, "organization data, reachable through the organization's own exports, not a personal account export", null));
        }
        // the organization table itself carries the org reference of every other row
        add(e, new Entry("organization", DataClass.ORG_TENANT, List.of(), "organization lifecycle (status CLOSED); created_by_user_id is SET NULL by its foreign key when the creator is erased", null, "organization data", null));

        Map<String, Entry> by = new LinkedHashMap<>();
        for (Entry x : e) by.put(x.table(), x); // a later entry for the same table (the two-column ones) replaces the single-column one
        ENTRIES = Collections.unmodifiableMap(by);
    }

    private DataMap() {}

    private static void add(List<Entry> list, Entry entry) {
        list.add(entry);
    }

    private static void owned(List<Entry> list, String table, String column, String erasure, String exportSection) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(new Col(column, Key.USER_ID)), erasure, exportSection, null, null));
    }

    private static void owned(List<Entry> list, String table, String column, String erasure, String exportSection, String exportNote) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(new Col(column, Key.USER_ID)), erasure, exportSection, exportNote, null));
    }

    private static void owned(List<Entry> list, String table, String column, String erasure, String exportSection, String exportNote, String retentionJob) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(new Col(column, Key.USER_ID)), erasure, exportSection, exportNote, retentionJob));
    }

    private static void ownedByLogin(List<Entry> list, String table, String column, String erasure, String exportSection, String exportNote) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(new Col(column, Key.LOGIN)), erasure, exportSection, exportNote, null));
    }

    private static void ownedByLogin(List<Entry> list, String table, String column, String erasure, String exportSection, String exportNote, String retentionJob) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(new Col(column, Key.LOGIN)), erasure, exportSection, exportNote, retentionJob));
    }

    private static void child(List<Entry> list, String table, String erasure, String exportSection) {
        list.add(new Entry(table, DataClass.USER_OWNED, List.of(), erasure, exportSection, null, null));
    }

    /** Every entry, by table name, in declaration order. */
    public static Map<String, Entry> entries() {
        return ENTRIES;
    }

    /** The entry of {@code table}, or null when the table is not classified (which {@code DataMapIT} turns into a failure). */
    public static Entry find(String table) {
        return table == null ? null : ENTRIES.get(table.toLowerCase());
    }

    /** The tables whose rows are counted per account before and after an erasure (those with a direct user column). */
    public static List<Entry> countable() {
        return ENTRIES.values().stream().filter(x -> !x.cols().isEmpty()).toList();
    }

    /** Every export section name any entry relies on. */
    public static Set<String> exportSections() {
        Set<String> out = new java.util.TreeSet<>();
        for (Entry x : ENTRIES.values()) if (x.exportSection() != null) out.add(x.exportSection());
        return out;
    }
}
